<?php
require_once __DIR__.'/../includes/auth.php';require_login();$cid=filter_input(INPUT_GET,'conversation_id',FILTER_VALIDATE_INT);$after=max(0,(int)($_GET['after_id']??0));$uid=current_user_id();$pdo->prepare('UPDATE users SET last_seen=NOW() WHERE user_id=?')->execute([$uid]);if(!$cid||!is_member($pdo,$cid,$uid))json_response(['error'=>'Not allowed'],403);
$st=$pdo->prepare("SELECT m.message_id,m.sender_id,COALESCE(m.message_text,'') AS message_text,m.message_type,m.attachment_path,m.attachment_name,m.edited_at,m.deleted_at,m.delivered_at,m.read_at,m.reply_to_id,DATE_FORMAT(m.sent_at,'%H:%i') AS time_label,u.full_name,u.profile_color, r.message_text AS reply_text,ru.full_name AS reply_sender FROM messages m JOIN users u ON u.user_id=m.sender_id LEFT JOIN messages r ON r.message_id=m.reply_to_id LEFT JOIN users ru ON ru.user_id=r.sender_id WHERE m.conversation_id=? AND m.message_id IN (SELECT recent.message_id FROM (SELECT message_id FROM messages WHERE conversation_id=? ORDER BY message_id DESC LIMIT 100) recent) ORDER BY m.message_id ASC");$st->execute([$cid,$cid]);$messages=$st->fetchAll();
$pdo->prepare('UPDATE messages SET delivered_at=COALESCE(delivered_at,NOW()) WHERE conversation_id=? AND sender_id<>?')->execute([$cid,$uid]);$pdo->prepare('UPDATE messages SET is_read=1,read_at=COALESCE(read_at,NOW()) WHERE conversation_id=? AND sender_id<>?')->execute([$cid,$uid]);$pdo->prepare('UPDATE conversation_members SET last_read_message_id=GREATEST(last_read_message_id,COALESCE((SELECT MAX(message_id) FROM messages WHERE conversation_id=?),0)) WHERE conversation_id=? AND user_id=?')->execute([$cid,$cid,$uid]);$pdo->prepare('UPDATE notifications SET is_read=1 WHERE user_id=? AND conversation_id=?')->execute([$uid,$cid]);
$st=$pdo->prepare('SELECT u.full_name FROM typing_status t JOIN users u ON u.user_id=t.user_id WHERE t.conversation_id=? AND t.user_id<>? AND t.updated_at>DATE_SUB(NOW(),INTERVAL 5 SECOND)');$st->execute([$cid,$uid]);$typing=array_column($st->fetchAll(),'full_name');
json_response(['messages'=>$messages,'receipts'=>[],'typing'=>$typing]);
